# APRON numerical abstract domains: the C libraries (libapron.a and the
# domains: box, octagons, newpolka, taylor1plus, avoct) and the OCaml stubs
# generated by camlidl (libapron_caml.a, lib<domain><num>_caml.a).
#
# wasm has no FPU rounding-mode control: ap_fpu_init fails and the box/oct
# managers print a warning when allocated.  The exact (MPQ) domains are not
# affected; the double (D) ones round to nearest.

SOURCE=opam:apron
DEPENDS="mlgmpidl camlidl gmp mpfr"

APRON_DOMAINS="box:box octagons:oct newpolka:polka taylor1plus:t1p avoct:avo"

build() {
  # objects of the native build, when the sources are opam's build directory
  find . \( -name '*.o' -o -name '*.a' -o -name '*.so' \) -delete
  GMP_PREFIX=$SYSROOT MPFR_PREFIX=$SYSROOT emconfigure ./configure -prefix "$SYSROOT" \
    -no-ocaml -no-cxx -no-java -no-ppl -no-pplite -no-glpk -no-strip >&2
  # C libraries, static only
  local cflags="$CFLAGS -U__STRICT_ANSI__ -std=c99 -I$SYSROOT/include"
  emmake make c HAS_SHARED= CC="$EMCC" AR="$EMAR" RANLIB=true \
    CFLAGS="$cflags -DNDEBUG" CFLAGS_DEBUG="$cflags" -j"$NPROC" >&2
  local a
  while IFS= read -r a; do install_lib "$a"; provides apron "$(basename "$a" .a | sed 's/^lib//')"
  done < <(find . -name 'lib*.a' ! -name '*_debug.a' ! -path './japron/*')
  install_headers apron apron/*.h num/*.h itv/*.h mlapronidl/apron_caml.h

  # OCaml stubs: the camlidl output is in the opam build directory, or is
  # regenerated with the host camlidl.  -std=c99 as in apron's own build: its
  # headers define bool, a keyword since C23.
  local inc="-std=c99 -Iapron -Inum -Iitv -Imlapronidl" m objs= ent dir pre lib num
  local idl
  idl=$(make_var mlapronidl IDLMODULES)
  for m in $idl; do
    [ -f "mlapronidl/${m}_caml.c" ] || make -C mlapronidl "${m}_caml.c" \
      CAMLIDL="$HOST_BIN/camlidl" PERL=perl MLGMPIDL_PREFIX="$SYSROOT" >&2
  done
  for m in mlapronidl/*_caml.c; do
    # shellcheck disable=SC2086
    stub_cc "$m" $inc; objs="$objs ${m%.c}.o"
  done
  # shellcheck disable=SC2086
  mklib apron_caml $objs
  install_lib libapron_caml.a
  link_flags apron_caml "-lapron -lmpfr -lgmp"
  provides apron apron_caml
  for ent in $APRON_DOMAINS; do
    dir=${ent%%:*} pre=${ent#*:}
    [ -f "$dir/${pre}_caml.c" ] || make -C "$dir" "${pre}_caml.c" \
      CAMLIDL="$HOST_BIN/camlidl" PERL=perl MLGMPIDL_PREFIX="$SYSROOT" >&2
    # shellcheck disable=SC2086
    stub_cc "$dir/${pre}_caml.c" $inc -I"$dir"
    # one stub object for every numeric variant of the domain's C library
    for lib in "$dir"/lib"$pre"*.a; do
      lib=$(basename "$lib" .a); lib=${lib#lib}
      case $lib in *_debug|*_caml) continue ;; esac
      num=${lib#"$pre"}
      ( cd "$dir" && mklib "$pre${num}_caml" "${pre}_caml.o" )
      install_lib "$dir/lib$pre${num}_caml.a"
      link_flags "$pre${num}_caml" "-l$lib -lapron -lmpfr -lgmp"
      provides apron "$pre${num}_caml"
    done
  done
}
